fn svn_protocol_put_contents(
    repo_path: &StdPath,
    path: &str,
    body: &Bytes,
) -> Result<Bytes, VcsError> {
    if !body.starts_with(b"SVN\0") {
        return Ok(body.clone());
    }
    let source = match yona_rust_vcs::svn_cat_file(repo_path, None, path) {
        Ok(bytes) => bytes,
        Err(VcsError::NotFound) => Vec::new(),
        Err(error) => return Err(error),
    };
    svn_protocol_apply_svndiff0(&source, body).map(Bytes::from)
}

fn svn_protocol_apply_svndiff0(source: &[u8], body: &[u8]) -> Result<Vec<u8>, VcsError> {
    if !body.starts_with(b"SVN\0") {
        return Err(VcsError::InvalidPath);
    }
    let mut cursor = 4;
    let mut target = Vec::new();
    while cursor < body.len() {
        let source_offset = svn_protocol_svndiff_int(body, &mut cursor)?;
        let source_length = svn_protocol_svndiff_int(body, &mut cursor)?;
        let target_length = svn_protocol_svndiff_int(body, &mut cursor)?;
        let instructions_length = svn_protocol_svndiff_int(body, &mut cursor)?;
        let new_data_length = svn_protocol_svndiff_int(body, &mut cursor)?;
        if cursor + instructions_length + new_data_length > body.len() {
            return Err(VcsError::InvalidPath);
        }
        let instructions = &body[cursor..cursor + instructions_length];
        cursor += instructions_length;
        let new_data = &body[cursor..cursor + new_data_length];
        cursor += new_data_length;
        let source_end = source_offset
            .checked_add(source_length)
            .ok_or(VcsError::InvalidPath)?;
        if source_end > source.len() {
            return Err(VcsError::InvalidPath);
        }
        let source_view = &source[source_offset..source_end];
        let window_start = target.len();
        let mut instruction_cursor = 0usize;
        let mut new_data_cursor = 0usize;
        while instruction_cursor < instructions.len() {
            let instruction = instructions[instruction_cursor];
            instruction_cursor += 1;
            let op = instruction >> 6;
            let inline_length = (instruction & 0x3f) as usize;
            let length = if inline_length == 0 {
                svn_protocol_svndiff_int(instructions, &mut instruction_cursor)?
            } else {
                inline_length
            };
            match op {
                0 => {
                    let offset = svn_protocol_svndiff_int(instructions, &mut instruction_cursor)?;
                    let end = offset.checked_add(length).ok_or(VcsError::InvalidPath)?;
                    if end > source_view.len() {
                        return Err(VcsError::InvalidPath);
                    }
                    target.extend_from_slice(&source_view[offset..end]);
                }
                1 => {
                    let offset = svn_protocol_svndiff_int(instructions, &mut instruction_cursor)?;
                    let start = window_start
                        .checked_add(offset)
                        .ok_or(VcsError::InvalidPath)?;
                    let end = start.checked_add(length).ok_or(VcsError::InvalidPath)?;
                    if end > target.len() {
                        return Err(VcsError::InvalidPath);
                    }
                    let copied = target[start..end].to_vec();
                    target.extend_from_slice(&copied);
                }
                2 => {
                    let end = new_data_cursor
                        .checked_add(length)
                        .ok_or(VcsError::InvalidPath)?;
                    if end > new_data.len() {
                        return Err(VcsError::InvalidPath);
                    }
                    target.extend_from_slice(&new_data[new_data_cursor..end]);
                    new_data_cursor = end;
                }
                _ => return Err(VcsError::InvalidPath),
            }
        }
        if target.len() - window_start != target_length || new_data_cursor != new_data.len() {
            return Err(VcsError::InvalidPath);
        }
    }
    Ok(target)
}

fn svn_protocol_svndiff_int(bytes: &[u8], cursor: &mut usize) -> Result<usize, VcsError> {
    let mut value = 0usize;
    loop {
        let byte = *bytes.get(*cursor).ok_or(VcsError::InvalidPath)?;
        *cursor += 1;
        value = value
            .checked_shl(7)
            .ok_or(VcsError::InvalidPath)?
            .checked_add((byte & 0x7f) as usize)
            .ok_or(VcsError::InvalidPath)?;
        if byte & 0x80 == 0 {
            return Ok(value);
        }
    }
}

fn svn_protocol_lock_response(
    repo_path: &StdPath,
    route: &SvnProtocolRoute,
    principal: Option<&persistence::AppUserRecord>,
    body: &Bytes,
) -> Response {
    let Some(actor) = principal else {
        return smart_http_basic_challenge_response();
    };
    let Some((_, path)) = svn_protocol_file_lookup_for_route(route) else {
        return svn_protocol_status_response(StatusCode::BAD_REQUEST);
    };
    let request = String::from_utf8_lossy(body);
    let comment = svn_protocol_xml_text(&request, "comment")
        .or_else(|| svn_protocol_xml_text(&request, "owner"))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "Yona WebDAV lock".to_string());
    let token = svn_protocol_new_lock_token();
    let lock =
        match yona_rust_vcs::svn_lock_path(repo_path, &path, &actor.login_id, &comment, &token) {
            Ok(lock) => lock,
            Err(VcsError::NotFound) => return svn_protocol_status_response(StatusCode::NOT_FOUND),
            Err(VcsError::InvalidPath) => {
                return svn_protocol_status_response(StatusCode::BAD_REQUEST)
            }
            Err(VcsError::SvnAdminUnavailable) | Err(VcsError::SvnLookUnavailable) => {
                return svn_protocol_not_implemented_response(route, "LOCK")
            }
            Err(VcsError::SvnAdminFailed(_)) => {
                return svn_protocol_status_response(
                    StatusCode::from_u16(423).expect("valid WebDAV Locked status"),
                )
            }
            Err(error) => {
                return RestRouteError::from_connect_error(internal_error(error)).into_response()
            }
        };
    let body = svn_protocol_lock_discovery_body(route, &lock);
    let mut response = (StatusCode::OK, body).into_response();
    add_svn_dav_headers(&mut response);
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/xml; charset=utf-8"),
    );
    if let Ok(value) = HeaderValue::from_str(&format!("<{}>", lock.token)) {
        response.headers_mut().insert("lock-token", value);
    }
    response
}

fn svn_protocol_unlock_response(
    repo_path: &StdPath,
    route: &SvnProtocolRoute,
    principal: Option<&persistence::AppUserRecord>,
    headers: &HeaderMap,
) -> Response {
    let Some(actor) = principal else {
        return smart_http_basic_challenge_response();
    };
    let Some((_, path)) = svn_protocol_file_lookup_for_route(route) else {
        return svn_protocol_status_response(StatusCode::BAD_REQUEST);
    };
    let Some(token) = svn_protocol_lock_token_header(headers) else {
        return svn_protocol_status_response(StatusCode::BAD_REQUEST);
    };
    match yona_rust_vcs::svn_unlock_path(repo_path, &path, &actor.login_id, &token) {
        Ok(()) => svn_protocol_status_response(StatusCode::NO_CONTENT),
        Err(VcsError::NotFound) => svn_protocol_status_response(StatusCode::NOT_FOUND),
        Err(VcsError::InvalidPath) => svn_protocol_status_response(StatusCode::BAD_REQUEST),
        Err(VcsError::SvnAdminUnavailable) => {
            svn_protocol_not_implemented_response(route, "UNLOCK")
        }
        Err(VcsError::SvnAdminFailed(_)) => svn_protocol_status_response(StatusCode::CONFLICT),
        Err(error) => RestRouteError::from_connect_error(internal_error(error)).into_response(),
    }
}

fn svn_protocol_get_locations_report_response(
    repo_path: &StdPath,
    route: &SvnProtocolRoute,
    request: &str,
) -> Response {
    let Some(location_revision) = svn_protocol_xml_i64(request, "location-revision") else {
        return svn_protocol_status_response(StatusCode::BAD_REQUEST);
    };
    let requested_path = svn_protocol_xml_text(request, "path").unwrap_or_default();
    let base_path = svn_protocol_file_lookup_for_route(route)
        .map(|(_, path)| path)
        .unwrap_or_default();
    let location_path = join_svn_report_path(&base_path, &requested_path);
    let exists =
        match yona_rust_vcs::svn_path_exists(repo_path, Some(location_revision), &location_path) {
            Ok(exists) => exists,
            Err(VcsError::InvalidPath) => {
                return svn_protocol_status_response(StatusCode::BAD_REQUEST)
            }
            Err(VcsError::NotFound) => return svn_protocol_status_response(StatusCode::NOT_FOUND),
            Err(VcsError::SvnLookUnavailable) => {
                return svn_protocol_not_implemented_response(route, "REPORT")
            }
            Err(error) => {
                return RestRouteError::from_connect_error(internal_error(error)).into_response()
            }
        };
    let location = if exists {
        format!(
            r#"  <S:location rev="{location_revision}" path="/{}"/>
"#,
            xml_escape(location_path.trim_matches('/'))
        )
    } else {
        String::new()
    };
    let body = format!(
        r#"<?xml version="1.0" encoding="utf-8"?>
<S:get-locations-report xmlns:S="svn:" xmlns:D="DAV:">
{location}</S:get-locations-report>"#
    );
    let mut response = (StatusCode::OK, body).into_response();
    add_svn_dav_headers(&mut response);
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/xml; charset=utf-8"),
    );
    response
}

fn svn_protocol_get_location_segments_report_response(
    repo_path: &StdPath,
    route: &SvnProtocolRoute,
    request: &str,
) -> Response {
    let Some(start_revision) = svn_protocol_xml_i64(request, "start-revision") else {
        return svn_protocol_status_response(StatusCode::BAD_REQUEST);
    };
    let end_revision = svn_protocol_xml_i64(request, "end-revision").unwrap_or(start_revision);
    let requested_path = svn_protocol_xml_text(request, "path").unwrap_or_default();
    let base_path = svn_protocol_file_lookup_for_route(route)
        .map(|(_, path)| path)
        .unwrap_or_default();
    let location_path = join_svn_report_path(&base_path, &requested_path);
    let exists =
        match yona_rust_vcs::svn_path_exists(repo_path, Some(start_revision), &location_path) {
            Ok(exists) => exists,
            Err(VcsError::InvalidPath) => {
                return svn_protocol_status_response(StatusCode::BAD_REQUEST)
            }
            Err(VcsError::NotFound) => return svn_protocol_status_response(StatusCode::NOT_FOUND),
            Err(VcsError::SvnLookUnavailable) => {
                return svn_protocol_not_implemented_response(route, "REPORT")
            }
            Err(error) => {
                return RestRouteError::from_connect_error(internal_error(error)).into_response()
            }
        };
    let segment = if exists {
        format!(
            r#"  <S:location-segment path="/{}" range-start="{start_revision}" range-end="{end_revision}"/>
"#,
            xml_escape(location_path.trim_matches('/'))
        )
    } else {
        String::new()
    };
    let body = format!(
        r#"<?xml version="1.0" encoding="utf-8"?>
<S:get-location-segments-report xmlns:S="svn:" xmlns:D="DAV:">
{segment}</S:get-location-segments-report>"#
    );
    let mut response = (StatusCode::OK, body).into_response();
    add_svn_dav_headers(&mut response);
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/xml; charset=utf-8"),
    );
    response
}

fn svn_protocol_lock_item(lock: &yona_rust_vcs::SvnLock) -> String {
    let comment = if lock.comment.is_empty() {
        String::new()
    } else {
        format!("    <S:comment>{}</S:comment>\n", xml_escape(&lock.comment))
    };
    let expiration = lock
        .expires
        .as_ref()
        .map(|value| {
            format!(
                "    <S:expirationdate>{}</S:expirationdate>\n",
                xml_escape(value)
            )
        })
        .unwrap_or_default();
    format!(
        r#"  <S:lock>
    <S:path>{}</S:path>
    <S:token>{}</S:token>
    <S:owner>{}</S:owner>
{comment}    <S:creationdate>{}</S:creationdate>
{expiration}  </S:lock>
"#,
        xml_escape(&lock.path),
        xml_escape(&lock.token),
        xml_escape(&lock.owner),
        xml_escape(&lock.created)
    )
}

fn svn_protocol_log_item(entry: &yona_rust_vcs::SvnLogEntry) -> String {
    format!(
        r#"  <S:log-item>
    <D:version-name>{}</D:version-name>
    <S:creator-displayname>{}</S:creator-displayname>
    <S:date>{}</S:date>
    <D:comment>{}</D:comment>
  </S:log-item>
"#,
        entry.revision,
        xml_escape(&entry.author),
        xml_escape(&svn_protocol_committed_date(&entry.date)),
        xml_escape(&entry.message)
    )
}

fn svn_protocol_file_rev_item(
    path: &str,
    entry: &yona_rust_vcs::SvnLogEntry,
    contents: &[u8],
) -> String {
    let txdelta = general_purpose::STANDARD.encode(svn_protocol_svndiff0_fulltext(contents));
    format!(
        r#"  <S:file-rev path="/{}" rev="{}">
    <S:rev-prop name="svn:author">{}</S:rev-prop>
    <S:rev-prop name="svn:date">{}</S:rev-prop>
    <S:rev-prop name="svn:log">{}</S:rev-prop>
    <S:txdelta>{}</S:txdelta>
  </S:file-rev>
"#,
        xml_escape(path.trim_matches('/')),
        entry.revision,
        xml_escape(&entry.author),
        xml_escape(&svn_protocol_committed_date(&entry.date)),
        xml_escape(&entry.message),
        txdelta
    )
}

fn svn_protocol_svndiff0_fulltext(contents: &[u8]) -> Vec<u8> {
    let mut encoded = b"SVN\0".to_vec();
    let mut instructions = Vec::new();
    if !contents.is_empty() {
        instructions.push(0x80);
        svn_protocol_push_svndiff_int(&mut instructions, contents.len());
    }
    for value in [0, 0, contents.len(), instructions.len(), contents.len()] {
        svn_protocol_push_svndiff_int(&mut encoded, value);
    }
    encoded.extend_from_slice(&instructions);
    encoded.extend_from_slice(contents);
    encoded
}

fn svn_protocol_push_svndiff_int(output: &mut Vec<u8>, value: usize) {
    let mut groups = Vec::new();
    let mut remaining = value;
    groups.push((remaining & 0x7f) as u8);
    remaining >>= 7;
    while remaining > 0 {
        groups.push((remaining & 0x7f) as u8);
        remaining >>= 7;
    }
    for (index, group) in groups.iter().rev().enumerate() {
        let has_more = index + 1 < groups.len();
        output.push(if has_more { *group | 0x80 } else { *group });
    }
}

fn svn_protocol_replay_included(path: &str, filter_path: Option<&str>) -> bool {
    let Some(filter_path) = filter_path else {
        return true;
    };
    let path = path.trim_matches('/');
    let filter_path = filter_path.trim_matches('/');
    path == filter_path || path.starts_with(&format!("{filter_path}/"))
}

fn svn_protocol_update_depth_includes(entry: &yona_rust_vcs::SvnTreeEntry, depth: &str) -> bool {
    match depth.to_ascii_lowercase().as_str() {
        "empty" => false,
        "files" => !entry.is_dir,
        _ => true,
    }
}

fn svn_protocol_update_entries_recursive(
    route: &SvnProtocolRoute,
    entries: &[yona_rust_vcs::SvnTreeEntry],
    parent_path: &str,
    revision: i64,
    base_revision: i64,
    revision_log: &yona_rust_vcs::SvnLogEntry,
    indent_level: usize,
    start_empty: bool,
    repo_path: &StdPath,
    inline_text_deltas: bool,
) -> String {
    let parent_path = parent_path.trim_matches('/');
    let child_names = entries
        .iter()
        .filter_map(|entry| svn_protocol_immediate_child_name(parent_path, &entry.path))
        .collect::<std::collections::BTreeSet<_>>();
    let mut output = String::new();
    for name in child_names {
        let child_path = if parent_path.is_empty() {
            name.clone()
        } else {
            format!("{parent_path}/{name}")
        };
        let child_entry = entries
            .iter()
            .find(|entry| entry.path.trim_matches('/') == child_path);
        let is_dir = child_entry.map(|entry| entry.is_dir).unwrap_or_else(|| {
            entries.iter().any(|entry| {
                entry
                    .path
                    .trim_matches('/')
                    .starts_with(&format!("{child_path}/"))
            })
        });
        if is_dir {
            let indent = "  ".repeat(indent_level);
            let child_indent = "  ".repeat(indent_level + 1);
            let nested = svn_protocol_update_entries_recursive(
                route,
                entries,
                &child_path,
                revision,
                base_revision,
                revision_log,
                indent_level + 1,
                start_empty,
                repo_path,
                inline_text_deltas,
            );
            let directory_element = if start_empty {
                "add-directory"
            } else {
                "open-directory"
            };
            let revision_attribute = if start_empty {
                String::new()
            } else {
                format!(r#" rev="{base_revision}""#)
            };
            output.push_str(&format!(
                r#"{indent}<S:{directory_element} name="{}"{revision_attribute} bc-url="{}">
{child_indent}<D:checked-in><D:href>{}</D:href></D:checked-in>
{}
{}{indent}</S:{directory_element}>
"#,
                xml_escape(&name),
                xml_escape(&svn_protocol_baseline_collection_href(
                    route,
                    revision,
                    &child_path
                )),
                xml_escape(&svn_protocol_version_href(route, revision, &child_path)),
                svn_protocol_update_entry_props(revision_log, indent_level + 1),
                nested
            ));
        } else if let Some(entry) = child_entry {
            let inline_delta = if inline_text_deltas {
                yona_rust_vcs::svn_cat_file(repo_path, Some(revision), entry.path.trim_matches('/'))
                    .ok()
            } else {
                None
            };
            output.push_str(&svn_protocol_update_file_entry(
                route,
                entry,
                revision,
                base_revision,
                revision_log,
                indent_level,
                start_empty,
                inline_delta.as_deref(),
            ));
        }
    }
    output
}

fn svn_protocol_immediate_child_name(parent_path: &str, path: &str) -> Option<String> {
    let path = path.trim_matches('/');
    if path.is_empty() || path == parent_path {
        return None;
    }
    let relative = if parent_path.is_empty() {
        path
    } else {
        path.strip_prefix(&format!("{parent_path}/"))?
    };
    relative.split('/').next().map(str::to_string)
}

fn svn_protocol_update_file_entry(
    route: &SvnProtocolRoute,
    entry: &yona_rust_vcs::SvnTreeEntry,
    revision: i64,
    base_revision: i64,
    revision_log: &yona_rust_vcs::SvnLogEntry,
    indent_level: usize,
    start_empty: bool,
    inline_delta: Option<&[u8]>,
) -> String {
    let indent = "  ".repeat(indent_level);
    let child_indent = "  ".repeat(indent_level + 1);
    let name = entry
        .path
        .trim_matches('/')
        .rsplit('/')
        .next()
        .unwrap_or(entry.path.as_str());
    let checked_in_revision = if inline_delta.is_some() && !start_empty {
        base_revision
    } else {
        revision
    };
    let version_href =
        svn_protocol_version_href(route, checked_in_revision, entry.path.trim_matches('/'));
    let file_element = if start_empty { "add-file" } else { "open-file" };
    let revision_attribute = if start_empty {
        String::new()
    } else {
        format!(r#" rev="{base_revision}""#)
    };
    let inline_props = if let Some(contents) = inline_delta {
        format!(
            r#"{child_indent}<S:prop><V:md5-checksum xmlns:V="{}">{}</V:md5-checksum></S:prop>
"#,
            "http://subversion.tigris.org/xmlns/dav/",
            svn_protocol_md5_hex(contents)
        )
    } else {
        String::new()
    };
    let file_text = if let Some(contents) = inline_delta {
        format!(
            r#"{child_indent}<S:txdelta>{}</S:txdelta>
"#,
            general_purpose::STANDARD.encode(svn_protocol_svndiff0_fulltext(contents))
        )
    } else {
        format!("{child_indent}<S:fetch-file/>\n")
    };
    format!(
        r#"{indent}<S:{file_element} name="{}"{revision_attribute}>
{child_indent}<D:checked-in><D:href>{}</D:href></D:checked-in>
{}
{inline_props}
{child_indent}<S:baseline-relative-path>{}</S:baseline-relative-path>
{file_text}
{indent}</S:{file_element}>
"#,
        xml_escape(name),
        xml_escape(&version_href),
        svn_protocol_update_entry_props(revision_log, indent_level + 1),
        xml_escape(entry.path.trim_matches('/'))
    )
}

fn svn_protocol_md5_hex(contents: &[u8]) -> String {
    let mut hasher = Md5::new();
    hasher.update(contents);
    format!("{:x}", hasher.finalize())
}

fn svn_protocol_update_inline_text_deltas(request: &str) -> bool {
    request.contains("<S:dst-path>")
        && !svn_protocol_xml_text(request, "text-deltas")
            .as_deref()
            .is_some_and(|value| value.eq_ignore_ascii_case("no"))
}

fn svn_protocol_update_entry_props(
    revision_log: &yona_rust_vcs::SvnLogEntry,
    indent_level: usize,
) -> String {
    let indent = "  ".repeat(indent_level);
    let mut props = format!(
        r#"{indent}<S:set-prop name="svn:entry:committed-rev">{}</S:set-prop>
"#,
        revision_log.revision
    );
    if !revision_log.date.is_empty() {
        props.push_str(&format!(
            r#"{indent}<S:set-prop name="svn:entry:committed-date">{}</S:set-prop>
"#,
            xml_escape(&svn_protocol_committed_date(&revision_log.date))
        ));
    }
    if !revision_log.author.is_empty() {
        props.push_str(&format!(
            r#"{indent}<S:set-prop name="svn:entry:last-author">{}</S:set-prop>
"#,
            xml_escape(&revision_log.author)
        ));
    }
    props
}

fn svn_protocol_committed_date(svnlook_date: &str) -> String {
    let mut parts = svnlook_date.split_whitespace();
    let Some(date) = parts.next() else {
        return svnlook_date.trim().to_string();
    };
    let Some(time) = parts.next() else {
        return svnlook_date.trim().to_string();
    };
    let time = time.split_once('.').map(|(head, _)| head).unwrap_or(time);
    format!("{date}T{time}.000000Z")
}

fn svn_protocol_http_date(svnlook_date: &str) -> String {
    let mut parts = svnlook_date.split_whitespace();
    let Some(date) = parts.next() else {
        return svnlook_date.trim().to_string();
    };
    let Some(time) = parts.next() else {
        return svnlook_date.trim().to_string();
    };
    let timezone = parts.next();
    let Some((year, month, day)) = svn_protocol_parse_date_parts(date) else {
        return svnlook_date.trim().to_string();
    };
    let Some((hour, minute, second)) = svn_protocol_parse_time_parts(time) else {
        return svnlook_date.trim().to_string();
    };
    let local_seconds = svn_protocol_days_from_civil(year, month, day)
        .saturating_mul(86_400)
        .saturating_add(i64::from(hour) * 3_600 + i64::from(minute) * 60 + i64::from(second));
    let offset_seconds = timezone
        .and_then(svn_protocol_parse_timezone_offset)
        .unwrap_or_default();
    let utc_seconds = local_seconds.saturating_sub(offset_seconds);
    let days = utc_seconds.div_euclid(86_400);
    let seconds_of_day = utc_seconds.rem_euclid(86_400);
    let (year, month, day) = svn_protocol_civil_from_days(days);
    let hour = seconds_of_day / 3_600;
    let minute = (seconds_of_day % 3_600) / 60;
    let second = seconds_of_day % 60;
    let weekdays = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let months = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    let weekday = weekdays[(days + 4).rem_euclid(7) as usize];
    let month_name = months[(month - 1) as usize];
    format!("{weekday}, {day:02} {month_name} {year:04} {hour:02}:{minute:02}:{second:02} GMT")
}

fn svn_protocol_parse_date_parts(date: &str) -> Option<(i64, i64, i64)> {
    let mut parts = date.split('-');
    let year = parts.next()?.parse().ok()?;
    let month = parts.next()?.parse().ok()?;
    let day = parts.next()?.parse().ok()?;
    (parts.next().is_none() && (1..=12).contains(&month) && (1..=31).contains(&day))
        .then_some((year, month, day))
}

fn svn_protocol_parse_time_parts(time: &str) -> Option<(i64, i64, i64)> {
    let time = time.split_once('.').map(|(head, _)| head).unwrap_or(time);
    let mut parts = time.split(':');
    let hour = parts.next()?.parse().ok()?;
    let minute = parts.next()?.parse().ok()?;
    let second = parts.next()?.parse().ok()?;
    (parts.next().is_none()
        && (0..=23).contains(&hour)
        && (0..=59).contains(&minute)
        && (0..=60).contains(&second))
    .then_some((hour, minute, second))
}

fn svn_protocol_parse_timezone_offset(timezone: &str) -> Option<i64> {
    let sign: i64 = match timezone.as_bytes().first()? {
        b'+' => 1,
        b'-' => -1,
        _ => return None,
    };
    if timezone.len() != 5 {
        return None;
    }
    let hour: i64 = timezone[1..3].parse().ok()?;
    let minute: i64 = timezone[3..5].parse().ok()?;
    ((0..=23).contains(&hour) && (0..=59).contains(&minute))
        .then_some(sign * (hour * 3_600 + minute * 60))
}

fn svn_protocol_days_from_civil(mut year: i64, month: i64, day: i64) -> i64 {
    if month <= 2 {
        year -= 1;
    }
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let year_of_era = year - era * 400;
    let month_prime = month + if month > 2 { -3 } else { 9 };
    let day_of_year = (153 * month_prime + 2) / 5 + day - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

fn svn_protocol_civil_from_days(days: i64) -> (i64, i64, i64) {
    let days = days + 719_468;
    let era = if days >= 0 { days } else { days - 146_096 } / 146_097;
    let day_of_era = days - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let mut year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_prime = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    if month <= 2 {
        year += 1;
    }
    (year, month, day)
}

fn svn_protocol_version_href(route: &SvnProtocolRoute, revision: i64, path: &str) -> String {
    let path = path.trim_matches('/');
    if path.is_empty() {
        format!("{}/!svn/ver/{revision}/", svn_protocol_project_href(route))
    } else {
        format!(
            "{}/!svn/ver/{revision}/{path}",
            svn_protocol_project_href(route)
        )
    }
}

fn svn_protocol_merge_href(project_href: &str, path: &str, collection: bool) -> String {
    let path = path.trim_matches('/');
    if path.is_empty() {
        return format!("{project_href}/");
    }
    if collection {
        format!("{project_href}/{path}/")
    } else {
        format!("{project_href}/{path}")
    }
}

fn svn_protocol_merge_version_href(project_href: &str, revision: i64, path: &str) -> String {
    let path = path.trim_matches('/');
    if path.is_empty() {
        format!("{project_href}/!svn/ver/{revision}/")
    } else {
        format!("{project_href}/!svn/ver/{revision}/{path}")
    }
}

fn svn_protocol_baseline_collection_href(
    route: &SvnProtocolRoute,
    revision: i64,
    path: &str,
) -> String {
    let path = path.trim_matches('/');
    if path.is_empty() {
        format!("{}/!svn/bc/{revision}/", svn_protocol_project_href(route))
    } else {
        format!(
            "{}/!svn/bc/{revision}/{path}",
            svn_protocol_project_href(route)
        )
    }
}

fn svn_protocol_update_depth(request: &str) -> String {
    if let Some(depth) = svn_protocol_xml_text(request, "depth") {
        return depth;
    }
    if svn_protocol_xml_text(request, "recursive")
        .as_deref()
        .is_some_and(|value| value.eq_ignore_ascii_case("no"))
    {
        return "files".to_string();
    }
    "infinity".to_string()
}

fn svn_protocol_update_start_empty(request: &str) -> bool {
    if !request.contains("<S:entry") {
        return true;
    }
    request.contains("start-empty=\"true\"") || request.contains("start-empty='true'")
}

fn svn_protocol_update_entry_revision(request: &str) -> Option<i64> {
    let entry_start = request.find("<S:entry")?;
    let entry_end = request[entry_start..].find('>')? + entry_start;
    let entry = &request[entry_start..entry_end];
    ["rev=\"", "rev='"].iter().find_map(|marker| {
        let value = entry.split_once(marker)?.1;
        let quote = if *marker == "rev=\"" { '"' } else { '\'' };
        value.split_once(quote)?.0.parse::<i64>().ok()
    })
}

fn svn_protocol_replay_operation(
    path: &yona_rust_vcs::SvnChangedPath,
    low_water_mark: i64,
) -> String {
    let name = xml_escape(path.path.trim_matches('/'));
    match (&path.action, path.is_dir) {
        (yona_rust_vcs::SvnChangedAction::Added, true)
        | (yona_rust_vcs::SvnChangedAction::Replaced, true) => format!(
            r#"    <S:add-directory name="{name}">
    </S:add-directory>
"#
        ),
        (yona_rust_vcs::SvnChangedAction::Added, false)
        | (yona_rust_vcs::SvnChangedAction::Replaced, false) => format!(
            r#"    <S:add-file name="{name}">
      <S:close-file/>
    </S:add-file>
"#
        ),
        (yona_rust_vcs::SvnChangedAction::Deleted, _) => {
            format!(r#"    <S:delete-entry name="{name}" rev="{low_water_mark}"/>"#) + "\n"
        }
        (yona_rust_vcs::SvnChangedAction::Modified, true) => format!(
            r#"    <S:open-directory name="{name}" rev="{low_water_mark}">
    </S:open-directory>
"#
        ),
        (yona_rust_vcs::SvnChangedAction::Modified, false) => format!(
            r#"    <S:open-file name="{name}" rev="{low_water_mark}">
      <S:close-file/>
    </S:open-file>
"#
        ),
    }
}

fn svn_protocol_mergeinfo_item(path: &str, mergeinfo: &str) -> String {
    format!(
        r#"  <S:mergeinfo-item>
    <S:mergeinfo-path>/{}</S:mergeinfo-path>
    <S:mergeinfo-info>{}</S:mergeinfo-info>
  </S:mergeinfo-item>
"#,
        xml_escape(path.trim_matches('/')),
        xml_escape(mergeinfo)
    )
}

fn svn_protocol_list_item(
    repo_path: &StdPath,
    revision: i64,
    entry: &yona_rust_vcs::SvnTreeEntry,
    author: &str,
    date: &str,
) -> String {
    let node_kind = if entry.is_dir { "dir" } else { "file" };
    let size = if entry.is_dir {
        String::new()
    } else {
        match yona_rust_vcs::svn_cat_file(repo_path, Some(revision), &entry.path) {
            Ok(bytes) => format!(r#" size="{}""#, bytes.len()),
            Err(_) => String::new(),
        }
    };
    let date_attr = if date.trim().is_empty() {
        String::new()
    } else {
        format!(r#" date="{}""#, xml_escape(date))
    };
    let author_element = if author.trim().is_empty() {
        String::new()
    } else {
        format!(
            "    <D:creator-displayname>{}</D:creator-displayname>\n",
            xml_escape(author)
        )
    };
    format!(
        r#"  <S:item node-kind="{node_kind}"{size} created-rev="{revision}"{date_attr}>
{author_element}    {}
  </S:item>
"#,
        xml_escape(entry.path.trim_matches('/'))
    )
}

fn svn_protocol_inherited_props_item(item: &yona_rust_vcs::SvnInheritedPropertySet) -> String {
    item.properties
        .iter()
        .map(|property| {
            format!(
                "  <S:iprop-item>\n    <S:iprop-path>{}</S:iprop-path>\n    <S:iprop-propname>{}</S:iprop-propname>\n    <S:iprop-propval>{}</S:iprop-propval>\n  </S:iprop-item>\n",
                xml_escape(&item.path),
                xml_escape(&property.name),
                xml_escape(&property.value)
            )
        })
        .collect()
}

fn svn_protocol_xml_i64(xml: &str, tag: &str) -> Option<i64> {
    svn_protocol_xml_text(xml, tag)?.parse::<i64>().ok()
}

fn svn_protocol_xml_text(xml: &str, tag: &str) -> Option<String> {
    let start = xml
        .find(&format!("<S:{tag}>"))
        .or_else(|| xml.find(&format!("<D:{tag}>")))
        .or_else(|| xml.find(&format!("<{tag}>")))?;
    let value_start = xml[start..].find('>')? + start + 1;
    let end = xml[value_start..].find('<')? + value_start;
    Some(xml[value_start..end].trim().to_string())
}

fn svn_protocol_property_patches(request: &str) -> Option<Vec<yona_rust_vcs::SvnPropertyPatch>> {
    let mut patches = Vec::new();
    for section in svn_protocol_xml_sections(request, "set") {
        patches.extend(svn_protocol_property_elements(section, true));
    }
    for section in svn_protocol_xml_sections(request, "remove") {
        patches.extend(svn_protocol_property_elements(section, false));
    }
    Some(patches)
}

fn svn_protocol_proppatch_multistatus(
    route: &SvnProtocolRoute,
    path: &str,
    patches: &[yona_rust_vcs::SvnPropertyPatch],
) -> String {
    let href = svn_protocol_href(route, path, false);
    let mut properties = String::new();
    for patch in patches {
        properties.push_str(&format!("        <D:{}/>\n", xml_escape(&patch.name)));
    }
    format!(
        r#"<?xml version="1.0" encoding="utf-8"?>
<D:multistatus xmlns:D="DAV:">
  <D:response>
    <D:href>{}</D:href>
    <D:propstat>
      <D:prop>
{properties}      </D:prop>
      <D:status>HTTP/1.1 200 OK</D:status>
    </D:propstat>
  </D:response>
</D:multistatus>"#,
        xml_escape(&href)
    )
}

fn svn_protocol_xml_sections<'a>(xml: &'a str, tag: &str) -> Vec<&'a str> {
    let mut sections = Vec::new();
    let mut rest = xml;
    loop {
        let Some(open_start) = svn_protocol_find_xml_tag(rest, tag) else {
            break;
        };
        let after_open = &rest[open_start..];
        let Some(open_end) = after_open.find('>') else {
            break;
        };
        let content_start = open_start + open_end + 1;
        let Some(close_start_relative) =
            svn_protocol_find_xml_close_tag(&rest[content_start..], tag)
        else {
            break;
        };
        let content_end = content_start + close_start_relative;
        sections.push(&rest[content_start..content_end]);
        rest = &rest[content_end..];
    }
    sections
}

fn svn_protocol_find_xml_tag(xml: &str, tag: &str) -> Option<usize> {
    xml.find(&format!("<S:{tag}"))
        .or_else(|| xml.find(&format!("<s:{tag}")))
        .or_else(|| xml.find(&format!("<D:{tag}")))
        .or_else(|| xml.find(&format!("<d:{tag}")))
        .or_else(|| xml.find(&format!("<{tag}")))
}

fn svn_protocol_find_xml_close_tag(xml: &str, tag: &str) -> Option<usize> {
    xml.find(&format!("</S:{tag}>"))
        .or_else(|| xml.find(&format!("</s:{tag}>")))
        .or_else(|| xml.find(&format!("</D:{tag}>")))
        .or_else(|| xml.find(&format!("</d:{tag}>")))
        .or_else(|| xml.find(&format!("</{tag}>")))
}

fn svn_protocol_property_elements(
    section: &str,
    set_value: bool,
) -> Vec<yona_rust_vcs::SvnPropertyPatch> {
    let prop_body = svn_protocol_xml_sections(section, "prop")
        .into_iter()
        .next()
        .unwrap_or(section);
    let mut patches = Vec::new();
    let mut rest = prop_body;
    while let Some(open_start) = rest.find('<') {
        rest = &rest[open_start + 1..];
        if rest.starts_with('/') || rest.starts_with('!') || rest.starts_with('?') {
            continue;
        }
        let Some(open_end) = rest.find('>') else {
            break;
        };
        let raw_name = rest[..open_end]
            .split_whitespace()
            .next()
            .unwrap_or_default()
            .trim_end_matches('/');
        let Some(name) = svn_protocol_property_name(raw_name) else {
            rest = &rest[open_end + 1..];
            continue;
        };
        if set_value {
            let close_tag = format!("</{raw_name}>");
            let value_start = open_end + 1;
            let value = rest[value_start..]
                .find(&close_tag)
                .map(|end| rest[value_start..value_start + end].to_string())
                .unwrap_or_default();
            patches.push(yona_rust_vcs::SvnPropertyPatch {
                name,
                value: Some(value),
            });
        } else {
            patches.push(yona_rust_vcs::SvnPropertyPatch { name, value: None });
        }
        rest = &rest[open_end + 1..];
    }
    patches
}

fn svn_protocol_property_name(raw_name: &str) -> Option<String> {
    let raw_name = raw_name.trim();
    if raw_name.is_empty() {
        return None;
    }
    let local_name = raw_name
        .strip_prefix("C:")
        .or_else(|| raw_name.strip_prefix("c:"))
        .or_else(|| raw_name.strip_prefix("S:"))
        .or_else(|| raw_name.strip_prefix("s:"))
        .or_else(|| raw_name.strip_prefix("D:"))
        .or_else(|| raw_name.strip_prefix("d:"))
        .unwrap_or(raw_name);
    if local_name.eq_ignore_ascii_case("prop") || local_name.eq_ignore_ascii_case("propertyupdate")
    {
        return None;
    }
    Some(local_name.to_string())
}

fn svn_protocol_new_lock_token() -> String {
    let nanos = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    format!("opaquelocktoken:yona-{}-{nanos}", std::process::id())
}

fn svn_protocol_lock_token_header(headers: &HeaderMap) -> Option<String> {
    let value = headers.get("lock-token")?.to_str().ok()?.trim();
    let value = value
        .strip_prefix('<')
        .and_then(|token| token.strip_suffix('>'))
        .unwrap_or(value);
    if value.is_empty() {
        None
    } else {
        Some(value.to_string())
    }
}

fn svn_protocol_lock_discovery_body(
    route: &SvnProtocolRoute,
    lock: &yona_rust_vcs::SvnLock,
) -> String {
    let item = svn_protocol_lock_discovery_item(route, lock);
    format!(
        r#"<?xml version="1.0" encoding="utf-8"?>
<D:prop xmlns:D="DAV:">
{item}</D:prop>"#
    )
}

fn svn_protocol_lock_discovery_item(
    route: &SvnProtocolRoute,
    lock: &yona_rust_vcs::SvnLock,
) -> String {
    let href = format!("{}{}", svn_protocol_project_href(route), lock.path);
    let created = if lock.created.is_empty() {
        String::new()
    } else {
        format!(
            "\n        <D:creationdate>{}</D:creationdate>",
            xml_escape(&lock.created)
        )
    };
    format!(
        r#"        <D:lockdiscovery>
    <D:activelock>
      <D:locktype><D:write/></D:locktype>
      <D:lockscope><D:exclusive/></D:lockscope>
      <D:depth>0</D:depth>
      <D:owner>{}</D:owner>
      <D:timeout>Infinite</D:timeout>
      <D:locktoken><D:href>{}</D:href></D:locktoken>
      <D:lockroot><D:href>{}</D:href></D:lockroot>{created}
    </D:activelock>
  </D:lockdiscovery>
"#,
        xml_escape(&lock.owner),
        xml_escape(&lock.token),
        xml_escape(&href)
    )
}

fn join_svn_report_path(base_path: &str, requested_path: &str) -> String {
    let base_path = base_path.trim_matches('/');
    let requested_path = requested_path.trim_matches('/');
    if base_path.is_empty() {
        requested_path.to_string()
    } else if requested_path.is_empty() {
        base_path.to_string()
    } else {
        format!("{base_path}/{requested_path}")
    }
}

fn svn_protocol_file_lookup(svn_path: &str) -> Option<(Option<i64>, String)> {
    let trimmed = svn_path.trim_matches('/');
    if trimmed.is_empty() {
        return None;
    }
    if let Some(rest) = trimmed.strip_prefix("!svn/wrk/") {
        let (_, path) = rest.split_once('/').unwrap_or((rest, ""));
        return Some((None, path.to_string()));
    }
    if let Some(rest) = trimmed.strip_prefix("!svn/rvr/") {
        return svn_protocol_revision_path(rest);
    }
    if let Some(rest) = trimmed.strip_prefix("!svn/bc/") {
        return svn_protocol_revision_path(rest);
    }
    if let Some(rest) = trimmed.strip_prefix("!svn/ver/") {
        return svn_protocol_revision_path(rest);
    }
    if trimmed.starts_with("!svn/") {
        return None;
    }
    Some((None, trimmed.to_string()))
}

fn svn_protocol_file_lookup_for_route(route: &SvnProtocolRoute) -> Option<(Option<i64>, String)> {
    let (revision, path) = svn_protocol_file_lookup(&route.svn_path)?;
    Some((
        revision,
        svn_protocol_strip_project_path_alias(route, &path),
    ))
}

fn svn_protocol_labeled_route(route: &SvnProtocolRoute, headers: &HeaderMap) -> SvnProtocolRoute {
    let Some(revision) = svn_protocol_label_revision(headers) else {
        return route.clone();
    };
    let path = route.svn_path.trim_matches('/');
    let svn_path = if path.is_empty() {
        format!("!svn/bc/{revision}")
    } else if path.starts_with("!svn/") {
        path.to_string()
    } else {
        format!("!svn/ver/{revision}/{path}")
    };
    SvnProtocolRoute {
        svn_path,
        ..route.clone()
    }
}

fn svn_protocol_label_revision(headers: &HeaderMap) -> Option<i64> {
    headers
        .get("label")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.trim().parse::<i64>().ok())
}

fn svn_protocol_destination_file_lookup(
    route: &SvnProtocolRoute,
    destination: &str,
) -> Option<(Option<i64>, String)> {
    let svn_path = svn_protocol_repo_relative_request_path(route, destination);
    let destination_route = SvnProtocolRoute {
        base_path: route.base_path.clone(),
        request_origin: route.request_origin.clone(),
        owner_name: route.owner_name.clone(),
        project_name: route.project_name.clone(),
        svn_path,
    };
    svn_protocol_file_lookup_for_route(&destination_route)
}

fn svn_protocol_strip_project_path_alias(route: &SvnProtocolRoute, path: &str) -> String {
    let trimmed = path.trim_matches('/');
    if trimmed == route.project_name {
        return String::new();
    }
    if let Some(stripped) = trimmed.strip_prefix(&format!("{}/", route.project_name)) {
        return stripped.to_string();
    }
    path.to_string()
}

fn svn_protocol_revision_path(rest: &str) -> Option<(Option<i64>, String)> {
    let (revision, path) = rest.split_once('/').unwrap_or((rest, ""));
    let revision = revision.parse::<i64>().ok()?;
    Some((Some(revision), path.to_string()))
}

fn svn_protocol_activity_id(value: &str) -> Option<String> {
    let marker = "!svn/act/";
    let rest = value.split(marker).nth(1)?;
    let activity_id = rest
        .trim_start_matches('/')
        .split(['/', '?', '#'])
        .next()
        .unwrap_or_default()
        .trim();
    if activity_id.is_empty() {
        None
    } else {
        Some(activity_id.to_string())
    }
}

fn svn_protocol_working_activity_id(value: &str) -> Option<String> {
    let marker = "!svn/wrk/";
    let rest = value.split(marker).nth(1)?;
    let activity_id = rest
        .trim_start_matches('/')
        .split(['/', '?', '#'])
        .next()
        .unwrap_or_default()
        .trim();
    if activity_id.is_empty() {
        None
    } else {
        Some(activity_id.to_string())
    }
}

fn add_svn_dav_headers(response: &mut Response) {
    response
        .headers_mut()
        .insert("dav", HeaderValue::from_static("1,2"));
    response
        .headers_mut()
        .insert("ms-author-via", HeaderValue::from_static("DAV"));
}

fn xml_escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn svn_protocol_not_implemented_response(route: &SvnProtocolRoute, method: &str) -> Response {
    let mut response = (
        StatusCode::NOT_IMPLEMENTED,
        format!(
            "SVN protocol serving is not implemented yet for {}/{} ({method} {})",
            route.owner_name, route.project_name, route.svn_path
        ),
    )
        .into_response();
    add_svn_dav_headers(&mut response);
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        HeaderValue::from_static("text/plain; charset=utf-8"),
    );
    response
}

async fn direct_smart_http_request(
    request: Request,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
    public_origin: String,
) -> Response {
    let Some(route) = smart_http_route_from_path(request.uri().path(), &base_path) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let (parts, body) = request.into_parts();
    let method = parts.method.as_str().to_ascii_uppercase();
    if method != "GET" && method != "POST" {
        return StatusCode::METHOD_NOT_ALLOWED.into_response();
    }
    let query_string = parts.uri.query().unwrap_or_default().to_string();
    if method == "GET" && route.git_path == "info/refs" && !smart_http_has_service(&query_string) {
        return (StatusCode::FORBIDDEN, "Unsupported service: getanyfile").into_response();
    }
    if method == "POST" && smart_http_announced_body_too_large(&parts.headers) {
        return (StatusCode::PAYLOAD_TOO_LARGE, "Request Entity Too Large").into_response();
    }

    let PilotBackend::Repository(repository) = &backend else {
        return StatusCode::NOT_IMPLEMENTED.into_response();
    };
    let principal =
        match smart_http_principal_from_headers(&parts.headers, &session_manager, repository).await
        {
            Ok(principal) => principal,
            Err(response) => return response,
        };
    let actor_id = principal.as_ref().map(|user| user.id);
    let remote_user = principal.as_ref().map(|user| user.login_id.clone());
    let authorization = match repository
        .read_project_authorization(&route.owner_name, &route.project_name, actor_id)
        .await
    {
        Ok(Some(authorization)) => authorization,
        Ok(None) => return (StatusCode::NOT_FOUND, "Repository not found").into_response(),
        Err(error) => {
            return RestRouteError::from_connect_error(internal_error(error)).into_response()
        }
    };
    if !authorization.project.vcs.eq_ignore_ascii_case("GIT") {
        return (StatusCode::NOT_FOUND, "Repository not found").into_response();
    }

    let permission = if smart_http_requires_write(&route.git_path, &query_string) {
        SmartHttpPermission::Write
    } else {
        SmartHttpPermission::Read
    };
    match smart_http_authorization(&authorization, actor_id.is_none(), permission) {
        Ok(()) => {}
        Err(SmartHttpAccessFailure::AuthenticationRequired) => {
            return smart_http_basic_challenge_response();
        }
        Err(SmartHttpAccessFailure::Forbidden) => {
            return (StatusCode::FORBIDDEN, "Forbidden").into_response();
        }
        Err(SmartHttpAccessFailure::InvalidProjectScope(error)) => {
            return RestRouteError::from_connect_error(error).into_response();
        }
    }

    let body_bytes = match body.collect().await {
        Ok(collected) => collected.to_bytes(),
        Err(error) => {
            return RestRouteError::from_connect_error(internal_error(error)).into_response();
        }
    };
    if body_bytes.len() > MAX_SMART_HTTP_RPC_BYTES {
        return (StatusCode::PAYLOAD_TOO_LARGE, "Request Entity Too Large").into_response();
    }

    let repo_root = yona_data_root().join("repo");
    let path_info = format!("/{}.git/{}", authorization.project.id, route.git_path);
    let content_type = parts
        .headers
        .get(http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok());
    let git_protocol = parts
        .headers
        .get("git-protocol")
        .and_then(|value| value.to_str().ok());
    let remote_addr = smart_http_remote_addr(&parts.headers);
    let repo_path = yona_rust_vcs::repository_path(&yona_data_root(), authorization.project.id);
    let is_receive_pack_post = method == "POST" && route.git_path == "git-receive-pack";
    let before_refs = if is_receive_pack_post {
        match yona_rust_vcs::read_head_refs(&repo_path) {
            Ok(refs) => refs,
            Err(error) => {
                return RestRouteError::from_connect_error(internal_error(error)).into_response()
            }
        }
    } else {
        Vec::new()
    };

    let response = yona_rust_vcs::run_git_http_backend(GitHttpBackendRequest {
        body: &body_bytes,
        content_type,
        git_protocol,
        method: &method,
        path_info: &path_info,
        query_string: &query_string,
        remote_addr: &remote_addr,
        remote_user: remote_user.as_deref(),
        repo_root: &repo_root,
    });

    match response {
        Ok(output) => {
            if is_receive_pack_post && (200..300).contains(&output.status) {
                if let Some(actor) = principal.as_ref() {
                    record_smart_http_push_side_effects(
                        repository,
                        &authorization.project,
                        actor,
                        &repo_path,
                        before_refs,
                        &public_origin,
                        &base_path,
                    )
                    .await;
                }
            }
            smart_http_backend_response(output)
        }
        Err(VcsError::NotFound) => (StatusCode::NOT_FOUND, "Repository not found").into_response(),
        Err(VcsError::GitUnavailable) => (
            StatusCode::SERVICE_UNAVAILABLE,
            "git executable is unavailable",
        )
            .into_response(),
        Err(VcsError::GitTimedOut) => {
            (StatusCode::GATEWAY_TIMEOUT, "git command timed out").into_response()
        }
        Err(VcsError::GitFailed(message))
            if message.contains("Smart HTTP request body exceeds limit") =>
        {
            (StatusCode::PAYLOAD_TOO_LARGE, "Request Entity Too Large").into_response()
        }
        Err(error) => RestRouteError::from_connect_error(internal_error(error)).into_response(),
    }
}

fn smart_http_route_from_path(path: &str, base_path: &str) -> Option<SmartHttpRoute> {
    let mut relative = path;
    if base_path != "/" {
        if relative == base_path {
            relative = "/";
        } else if let Some(stripped) = relative.strip_prefix(&format!("{base_path}/")) {
            relative = stripped;
        }
    }
    let segments = relative
        .trim_start_matches('/')
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    if segments.len() < 3 {
        return None;
    }
    let owner_name = segments[0].to_string();
    let project_segment = segments[1];
    let git_path = match segments[2..] {
        ["info", "refs"] => "info/refs",
        ["git-upload-pack"] => "git-upload-pack",
        ["git-receive-pack"] => "git-receive-pack",
        _ => return None,
    }
    .to_string();

    let project_name = project_segment
        .strip_suffix(".git")
        .unwrap_or(project_segment)
        .to_string();
    if owner_name.is_empty() || project_name.is_empty() {
        return None;
    }

    Some(SmartHttpRoute {
        git_path,
        owner_name,
        project_name,
    })
}

fn svn_protocol_route_from_path(path: &str, base_path: &str) -> Option<SvnProtocolRoute> {
    let mut relative = path;
    if base_path != "/" {
        if relative == base_path {
            relative = "/";
        } else if let Some(stripped) = relative.strip_prefix(&format!("{base_path}/")) {
            relative = stripped;
        }
    }
    let segments = relative
        .trim_start_matches('/')
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    if segments.len() < 3 || segments[0] != "svn" {
        return None;
    }
    let owner_name = segments[1].to_string();
    let project_name = segments[2].to_string();
    if owner_name.is_empty() || project_name.is_empty() {
        return None;
    }
    Some(SvnProtocolRoute {
        base_path: base_path.to_string(),
        request_origin: None,
        owner_name,
        project_name,
        svn_path: segments[3..].join("/"),
    })
}

fn smart_http_has_service(query_string: &str) -> bool {
    query_string
        .split('&')
        .filter_map(|pair| pair.split_once('='))
        .any(|(name, value)| name == "service" && !value.trim().is_empty())
}

fn smart_http_requires_write(git_path: &str, query_string: &str) -> bool {
    git_path == "git-receive-pack"
        || query_string
            .split('&')
            .filter_map(|pair| pair.split_once('='))
            .any(|(name, value)| name == "service" && value == "git-receive-pack")
}

fn smart_http_announced_body_too_large(headers: &HeaderMap) -> bool {
    headers
        .get(http::header::CONTENT_LENGTH)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<usize>().ok())
        .is_some_and(|length| length > MAX_SMART_HTTP_RPC_BYTES)
}

#[derive(Clone, Debug)]
enum SmartHttpAccessFailure {
    AuthenticationRequired,
    Forbidden,
    InvalidProjectScope(ConnectError),
}

fn smart_http_authorization(
    authorization: &persistence::ProjectAuthorizationRecord,
    is_anonymous: bool,
    permission: SmartHttpPermission,
) -> Result<(), SmartHttpAccessFailure> {
    let scope = map_project_scope(&authorization.project.project_scope)
        .map_err(SmartHttpAccessFailure::InvalidProjectScope)?;
    if authorization.viewer.is_site_admin
        || authorization.viewer.is_organization_admin
        || authorization.viewer.is_project_manager
    {
        return Ok(());
    }

    let requires_write = permission == SmartHttpPermission::Write
        || (permission == SmartHttpPermission::Read
            && authorization.project.is_code_accessible_member_only);
    if requires_write {
        if authorization.viewer.is_project_member
            || (authorization.viewer.is_organization_member
                && matches!(scope, ProjectScope::Public | ProjectScope::Protected))
        {
            return Ok(());
        }
        return if is_anonymous {
            Err(SmartHttpAccessFailure::AuthenticationRequired)
        } else {
            Err(SmartHttpAccessFailure::Forbidden)
        };
    }

    if matches!(scope, ProjectScope::Public)
        || authorization.viewer.is_project_member
        || (authorization.viewer.is_organization_member && matches!(scope, ProjectScope::Protected))
    {
        return Ok(());
    }

    if is_anonymous {
        Err(SmartHttpAccessFailure::AuthenticationRequired)
    } else {
        Err(SmartHttpAccessFailure::Forbidden)
    }
}

async fn smart_http_principal_from_headers(
    headers: &HeaderMap,
    session_manager: &SessionManager,
    repository: &PilotRepository,
) -> Result<Option<persistence::AppUserRecord>, Response> {
    match parse_basic_authorization(headers) {
        Ok(Some((identifier, secret))) => {
            let Some(user) = repository
                .find_user_by_identifier(&identifier)
                .await
                .map_err(|error| {
                    RestRouteError::from_connect_error(internal_error(error)).into_response()
                })?
            else {
                return Err(smart_http_basic_challenge_response());
            };
            let password_matches = verify(&secret, &user.password_hash).unwrap_or(false);
            let token_matches = repository
                .read_api_token_for_user(user.id)
                .await
                .map_err(|error| {
                    RestRouteError::from_connect_error(internal_error(error)).into_response()
                })?
                .is_some_and(|token| !token.is_empty() && token == secret);
            if !(password_matches || token_matches) {
                return Err(smart_http_basic_challenge_response());
            }
            if confirmation_session_required() && !user.is_confirmed {
                return Err(smart_http_basic_challenge_response());
            }
            Ok(Some(user))
        }
        Ok(None) => {
            let Some(session) = session_manager.read_session_from_headers(headers) else {
                return Ok(None);
            };
            let Some(user_id) = session.user_id else {
                return Ok(None);
            };
            repository.find_user_by_id(user_id).await.map_err(|error| {
                RestRouteError::from_connect_error(internal_error(error)).into_response()
            })
        }
        Err(()) => Err(smart_http_basic_challenge_response()),
    }
}

fn parse_basic_authorization(headers: &HeaderMap) -> Result<Option<(String, String)>, ()> {
    let Some(value) = headers.get(AUTHORIZATION) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|_| ())?;
    let Some(encoded) = value
        .trim()
        .strip_prefix("Basic ")
        .or_else(|| value.trim().strip_prefix("basic "))
    else {
        return Ok(None);
    };
    let decoded = general_purpose::STANDARD.decode(encoded).map_err(|_| ())?;
    let Some(separator) = decoded.iter().position(|byte| *byte == b':') else {
        return Err(());
    };
    let login_id = iso_8859_1_bytes_to_string(&decoded[..separator]);
    let password = iso_8859_1_bytes_to_string(&decoded[separator + 1..]);
    Ok(Some((login_id, password)))
}

fn iso_8859_1_bytes_to_string(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| char::from(*byte)).collect()
}

fn smart_http_basic_challenge_response() -> Response {
    let mut response = (StatusCode::UNAUTHORIZED, LEGACY_LOGIN_REQUIRED_MESSAGE).into_response();
    response.headers_mut().insert(
        WWW_AUTHENTICATE,
        HeaderValue::from_static("Basic realm=\"Yona\""),
    );
    response
}

fn smart_http_remote_addr(headers: &HeaderMap) -> String {
    headers
        .get("x-forwarded-for")
        .or_else(|| headers.get("x-real-ip"))
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(',').next())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("127.0.0.1")
        .to_string()
}

fn smart_http_backend_response(output: yona_rust_vcs::GitHttpBackendResponse) -> Response {
    let status = StatusCode::from_u16(output.status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let mut response = (status, output.body).into_response();
    for (name, value) in output.headers {
        let Ok(name) = HeaderName::from_bytes(name.as_bytes()) else {
            continue;
        };
        let Ok(value) = HeaderValue::from_str(&value) else {
            continue;
        };
        if name == http::header::CONTENT_TYPE {
            response.headers_mut().insert(name, value);
        } else {
            response.headers_mut().append(name, value);
        }
    }
    response
}

async fn record_smart_http_push_side_effects(
    repository: &PilotRepository,
    project: &persistence::ProjectRecord,
    actor: &persistence::AppUserRecord,
    repo_path: &StdPath,
    before_refs: Vec<GitHeadRefRecord>,
    public_origin: &str,
    base_path: &str,
) {
    let Ok(summary) = smart_http_push_summary(repo_path, before_refs) else {
        return;
    };
    if summary.is_empty() {
        return;
    }
    let ref_names = summary.ref_names();
    let commit_count = summary.commits().len();
    let notification_message =
        legacy_push_notification_message(&project.project_name, commit_count, &ref_names);
    let _ = repository
        .record_git_push(
            project.id,
            actor.id,
            &summary.updated_branch_names(),
            &summary.deleted_branch_names(),
            &notification_message,
        )
        .await;
    record_pull_request_commit_changed_side_effects(
        repository,
        project,
        actor,
        &summary,
        public_origin,
        base_path,
    )
    .await;
    dispatch_git_push_webhooks(
        repository,
        project,
        actor,
        &summary,
        public_origin,
        base_path,
    )
    .await;
}

async fn record_pull_request_commit_changed_side_effects(
    repository: &PilotRepository,
    project: &persistence::ProjectRecord,
    actor: &persistence::AppUserRecord,
    summary: &SmartHttpPushSummary,
    public_origin: &str,
    base_path: &str,
) {
    let branches = summary
        .updated_refs
        .iter()
        .filter(|change| !change.commits.is_empty())
        .map(|change| persistence::PullRequestCommitChangedBranchInput {
            branch_name: change.short_ref.clone(),
            commits: change
                .commits
                .iter()
                .map(|commit| persistence::PullRequestPushedCommitInput {
                    author_email: commit.author_email.clone(),
                    commit_id: commit.commit_id.clone(),
                    commit_message: commit.message.clone(),
                })
                .collect(),
        })
        .collect::<Vec<_>>();
    if branches.is_empty() {
        return;
    }

    let Ok(changed) = repository
        .record_pull_request_commit_changes(persistence::PullRequestCommitChangedInput {
            actor_id: actor.id,
            actor_login_id: actor.login_id.clone(),
            branches,
            project_id: project.id,
        })
        .await
    else {
        return;
    };

    for record in changed {
        let detail_markdown = record.commit_messages.join("\n");
        dispatch_pull_request_webhooks(
            repository,
            &record.pull_request,
            actor,
            "PULL_REQUEST_COMMIT_CHANGED",
            &detail_markdown,
            None,
            None,
            public_origin,
            base_path,
        )
        .await;
    }
}

fn smart_http_push_summary(
    repo_path: &StdPath,
    before_refs: Vec<GitHeadRefRecord>,
) -> Result<SmartHttpPushSummary, VcsError> {
    let after_refs = yona_rust_vcs::read_head_refs(repo_path)?;
    let before_by_full_name = before_refs
        .iter()
        .map(|record| (record.full_name.clone(), record.clone()))
        .collect::<HashMap<_, _>>();
    let after_by_full_name = after_refs
        .iter()
        .map(|record| (record.full_name.clone(), record.clone()))
        .collect::<HashMap<_, _>>();
    let before_oids = before_refs
        .iter()
        .map(|record| record.object_id.clone())
        .collect::<Vec<_>>();

    let mut updated_refs = Vec::new();
    for after in after_refs {
        let before = before_by_full_name.get(&after.full_name);
        if before.is_some_and(|before| before.object_id == after.object_id) {
            continue;
        }
        let old_oid = before.map(|record| record.object_id.clone());
        let commits = yona_rust_vcs::read_push_commits(
            repo_path,
            old_oid.as_deref(),
            &after.object_id,
            &before_oids,
        )?;
        updated_refs.push(SmartHttpPushChange {
            commits,
            full_ref: after.full_name,
            new_oid: after.object_id,
            old_oid,
            short_ref: after.short_name,
        });
    }

    let deleted_refs = before_refs
        .into_iter()
        .filter(|before| !after_by_full_name.contains_key(&before.full_name))
        .collect::<Vec<_>>();

    Ok(SmartHttpPushSummary {
        deleted_refs,
        updated_refs,
    })
}

fn legacy_push_notification_message(
    project_name: &str,
    commit_count: usize,
    ref_names: &[String],
) -> String {
    if ref_names.len() == 1 {
        format!(
            "notification.pushed.commits.to: {project_name} {commit_count} {}",
            ref_names[0]
        )
    } else {
        format!("notification.pushed.commits: {project_name} {commit_count}")
    }
}

async fn dispatch_git_push_webhooks(
    repository: &PilotRepository,
    project: &persistence::ProjectRecord,
    actor: &persistence::AppUserRecord,
    summary: &SmartHttpPushSummary,
    public_origin: &str,
    base_path: &str,
) {
    let Ok(webhooks) = repository.list_project_webhooks(project.id).await else {
        return;
    };
    if webhooks.webhooks.is_empty() {
        return;
    }
    let commits = summary.commits();
    let body =
        git_push_webhook_payload(project, actor, summary, &commits, public_origin, base_path);
    for webhook in webhooks.webhooks {
        if !webhook.git_push {
            continue;
        }
        let webhook_type = project_webhook_type_label(webhook.webhook_type);
        let delivery = deliver_webhook(OutboundWebhook {
            body: body.clone(),
            event_type: "NEW_COMMIT".to_string(),
            payload_url: webhook.payload_url.clone(),
            secret: webhook.secret.clone(),
            webhook_type: webhook_type.clone(),
        });
        record_project_webhook_delivery(
            repository,
            &webhook,
            "NEW_COMMIT",
            &webhook_type,
            &body,
            &delivery,
        )
        .await;
    }
}

fn git_push_webhook_payload(
    project: &persistence::ProjectRecord,
    actor: &persistence::AppUserRecord,
    summary: &SmartHttpPushSummary,
    commits: &[GitPushCommitRecord],
    public_origin: &str,
    base_path: &str,
) -> String {
    let commit_values = commits
        .iter()
        .map(|commit| {
            serde_json::json!({
                "id": commit.commit_id.as_str(),
                "message": commit.message.as_str(),
                "timestamp": commit.timestamp.as_str(),
                "url": absolute_app_url(
                    public_origin,
                    base_path,
                    &format!(
                        "/{}/{}/commit/{}",
                        project.owner_name, project.project_name, commit.commit_id
                    ),
                ),
                "author": {
                    "name": commit.author_name.as_str(),
                    "email": commit.author_email.as_str(),
                },
                "committer": {
                    "name": commit.committer_name.as_str(),
                    "email": commit.committer_email.as_str(),
                },
            })
        })
        .collect::<Vec<_>>();
    let head_commit = commit_values
        .first()
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let ref_names = summary.ref_names();
    serde_json::json!({
        "ref": ref_names,
        "commits": commit_values,
        "head_commit": head_commit,
        "sender": {
            "login": actor.login_id.as_str(),
            "id": actor.id,
            "avatar_url": "",
            "type": "User",
            "site_admin": actor.is_site_admin,
        },
        "pusher": {
            "name": actor.display_name.as_str(),
            "email": actor.email_address.as_str(),
        },
        "repository": {
            "id": project.id,
            "name": project.project_name.as_str(),
            "owner": project.owner_name.as_str(),
            "html_url": base_path_href(
                base_path,
                &format!("/{}/{}", project.owner_name, project.project_name),
            ),
            "overview": project.overview.clone().unwrap_or_default(),
            "private": project.project_scope.eq_ignore_ascii_case("private"),
        },
    })
    .to_string()
}

fn percent_encode_uri_component(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    for byte in value.bytes() {
        if uri_component_unescaped(byte) {
            encoded.push(byte as char);
        } else {
            encoded.push_str(&format!("%{byte:02X}"));
        }
    }
    encoded
}

fn uri_component_unescaped(byte: u8) -> bool {
    matches!(
        byte,
        b'A'..=b'Z'
            | b'a'..=b'z'
            | b'0'..=b'9'
            | b'-'
            | b'_'
            | b'.'
            | b'!'
            | b'~'
            | b'*'
            | b'\''
            | b'('
            | b')'
    )
}

fn default_public_origin(configured: &str) -> String {
    let candidate = if configured.trim().is_empty() {
        std::env::var("YONA_PUBLIC_ORIGIN")
            .ok()
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| "http://localhost:3001".to_string())
    } else {
        configured.trim().to_string()
    };
    candidate.trim_end_matches('/').to_string()
}

fn absolute_app_url(public_origin: &str, base_path: &str, path: &str) -> String {
    format!("{public_origin}{}", base_path_href(base_path, path))
}

fn default_smtp_from() -> String {
    std::env::var("SMTP_FROM")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "noreply@yona.local".to_string())
}

fn notification_mail_recipient_allowed(email: &str) -> bool {
    let raw_domains = std::env::var("YONA_ALLOWED_MAIL_DOMAINS").unwrap_or_default();
    if raw_domains.trim().is_empty() {
        return true;
    }
    let Some((_, domain)) = email.rsplit_once('@') else {
        return false;
    };
    if domain.is_empty() {
        return false;
    }
    let domain = domain.to_ascii_lowercase();
    raw_domains
        .split(',')
        .map(|allowed| allowed.trim().to_ascii_lowercase())
        .any(|allowed| allowed == domain)
}

fn notification_mail_hide_addresses() -> bool {
    std::env::var("YONA_NOTIFICATION_MAIL_HIDE_ADDRESS")
        .ok()
        .and_then(|value| {
            let normalized = value.trim().to_ascii_lowercase();
            match normalized.as_str() {
                "false" | "0" | "no" | "off" => Some(false),
                "true" | "1" | "yes" | "on" => Some(true),
                _ => None,
            }
        })
        .unwrap_or(true)
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NotificationMailSchedulerConfig {
    pub enabled: bool,
    pub initial_delay_ms: u64,
    pub interval_ms: u64,
    pub delay_ms: i64,
}

impl Default for NotificationMailSchedulerConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            initial_delay_ms: 5_000,
            interval_ms: 60_000,
            delay_ms: 180_000,
        }
    }
}

pub fn notification_mail_scheduler_config_from_env() -> NotificationMailSchedulerConfig {
    let defaults = NotificationMailSchedulerConfig::default();
    NotificationMailSchedulerConfig {
        enabled: notification_mail_scheduler_enabled(),
        initial_delay_ms: notification_mail_duration_ms_env(
            "YONA_NOTIFICATION_MAIL_INITIAL_DELAY",
            defaults.initial_delay_ms,
        ),
        interval_ms: notification_mail_duration_ms_env(
            "YONA_NOTIFICATION_MAIL_INTERVAL",
            defaults.interval_ms,
        )
        .max(1),
        delay_ms: notification_mail_duration_ms_env(
            "YONA_NOTIFICATION_MAIL_DELAY",
            defaults.delay_ms as u64,
        )
        .min(i64::MAX as u64) as i64,
    }
}

fn notification_mail_scheduler_enabled() -> bool {
    std::env::var("YONA_NOTIFICATION_MAIL_ENABLED")
        .ok()
        .map(|value| {
            !matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "0" | "false" | "no" | "off"
            )
        })
        .unwrap_or(true)
}

fn notification_mail_duration_ms_env(name: &str, default_ms: u64) -> u64 {
    std::env::var(name)
        .ok()
        .and_then(|value| parse_legacy_duration_ms(&value))
        .unwrap_or(default_ms)
}

fn parse_legacy_duration_ms(value: &str) -> Option<u64> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    let (number, multiplier) = if let Some(number) = trimmed.strip_suffix("ms") {
        (number.trim(), 1)
    } else if let Some(number) = trimmed.strip_suffix('s') {
        (number.trim(), 1_000)
    } else if let Some(number) = trimmed.strip_suffix('m') {
        (number.trim(), 60_000)
    } else if let Some(number) = trimmed.strip_suffix('h') {
        (number.trim(), 3_600_000)
    } else {
        (trimmed, 1)
    };

    number
        .parse::<u64>()
        .ok()
        .and_then(|amount| amount.checked_mul(multiplier))
}

fn notification_mail_recipient_limit() -> Option<usize> {
    std::env::var("YONA_NOTIFICATION_MAIL_RECIPIENT_LIMIT")
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|limit| *limit > 0)
}

fn notification_mail_partial_recipient_size(hide_addresses: bool, recipient_count: usize) -> usize {
    let Some(limit) = notification_mail_recipient_limit() else {
        return recipient_count;
    };
    if hide_addresses {
        limit.saturating_sub(1)
    } else {
        limit
    }
}

fn notification_mail_content(
    item: &persistence::NotificationItemRecord,
    target_url: &str,
) -> (String, String) {
    let subject = if item.target_title.is_empty() {
        item.message.clone()
    } else {
        item.target_title.clone()
    };
    let body = if target_url.is_empty() {
        format!("{}\n\n{}", item.message, item.target_title)
    } else {
        format!("{}\n\n{}\n{}", item.message, item.target_title, target_url)
    };
    (subject, body)
}

pub async fn deliver_due_notification_mails(
    repository: &PilotRepository,
    now: DateTime,
    delay_ms: i64,
    public_origin: &str,
    base_path: &str,
) -> Result<usize, String> {
    let public_origin = default_public_origin(public_origin);
    let deliveries = repository
        .drain_due_notification_mail_deliveries(now, delay_ms)
        .await
        .map_err(|error| error.to_string())?;
    let deliveries: Vec<_> = deliveries
        .into_iter()
        .filter(|delivery| notification_mail_recipient_allowed(&delivery.recipient_email))
        .collect();
    let mut delivered = 0;
    if notification_mail_hide_addresses() {
        let mut grouped: Vec<(persistence::NotificationItemRecord, String, Vec<String>)> =
            Vec::new();
        for delivery in deliveries {
            if let Some((_, _, recipients)) = grouped.iter_mut().find(|(item, language, _)| {
                item.id == delivery.item.id && *language == delivery.recipient_language
            }) {
                recipients.push(delivery.recipient_email);
            } else {
                grouped.push((
                    delivery.item,
                    delivery.recipient_language,
                    vec![delivery.recipient_email],
                ));
            }
        }
        for (item, _, mut bcc) in grouped {
            bcc.sort();
            bcc.dedup();
            if bcc.is_empty() {
                continue;
            }
            let partial_recipient_size = notification_mail_partial_recipient_size(true, bcc.len());
            if partial_recipient_size == 0 {
                continue;
            }
            let target_url = if item.target_path.is_empty() {
                String::new()
            } else {
                absolute_app_url(&public_origin, base_path, &item.target_path)
            };
            let (subject, body) = notification_mail_content(&item, &target_url);
            for recipient_chunk in bcc.chunks(partial_recipient_size) {
                deliver(OutboundMail {
                    bcc: recipient_chunk.to_vec(),
                    body: body.clone(),
                    from: default_smtp_from(),
                    subject: subject.clone(),
                    to: default_smtp_from(),
                })
                .map_err(|error| error.to_string())?;
                delivered += 1;
            }
        }
        return Ok(delivered);
    }
    for delivery in deliveries {
        let target_url = if delivery.item.target_path.is_empty() {
            String::new()
        } else {
            absolute_app_url(&public_origin, base_path, &delivery.item.target_path)
        };
        let (subject, body) = notification_mail_content(&delivery.item, &target_url);
        deliver(OutboundMail {
            bcc: Vec::new(),
            body,
            from: default_smtp_from(),
            subject,
            to: delivery.recipient_email,
        })
        .map_err(|error| error.to_string())?;
        delivered += 1;
    }
    Ok(delivered)
}

pub async fn deliver_notification_mail_scheduler_tick(
    repository: &PilotRepository,
    config: &NotificationMailSchedulerConfig,
    public_origin: &str,
    base_path: &str,
) -> Result<usize, String> {
    if !config.enabled {
        return Ok(0);
    }
    deliver_due_notification_mails(
        repository,
        DateTimeUtc::from(SystemTime::now()).naive_utc(),
        config.delay_ms,
        public_origin,
        base_path,
    )
    .await
}

pub fn spawn_notification_mail_scheduler(
    repository: PilotRepository,
    public_origin: impl Into<String>,
    base_path: impl Into<String>,
    config: NotificationMailSchedulerConfig,
) -> Option<tokio::task::JoinHandle<()>> {
    if !config.enabled {
        return None;
    }
    let public_origin = public_origin.into();
    let base_path = base_path.into();
    Some(tokio::spawn(async move {
        if config.initial_delay_ms > 0 {
            tokio::time::sleep(Duration::from_millis(config.initial_delay_ms)).await;
        }
        loop {
            if let Err(error) = deliver_notification_mail_scheduler_tick(
                &repository,
                &config,
                &public_origin,
                &base_path,
            )
            .await
            {
                tracing::warn!(%error, "notification mail scheduler tick failed");
            }
            tokio::time::sleep(Duration::from_millis(config.interval_ms)).await;
        }
    }))
}

fn configured_site_name() -> String {
    std::env::var("YONA_SITE_NAME")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "Yona".to_string())
}

fn configured_project_default_scope() -> String {
    std::env::var("YONA_PROJECT_DEFAULT_SCOPE")
        .ok()
        .map(|value| normalize_identifier(&value))
        .filter(|value| matches!(value.as_str(), "public" | "protected" | "private"))
        .unwrap_or_else(|| "public".to_string())
}

fn configured_project_default_menus() -> Vec<String> {
    let Some(configured) = std::env::var("YONA_PROJECT_DEFAULT_MENUS")
        .ok()
        .filter(|value| !value.trim().is_empty())
    else {
        return default_project_menu_keys();
    };

    let menus = configured
        .split(',')
        .filter_map(
            |value| match normalize_project_default_menu_config_key(value).as_str() {
                "board" => Some("board".to_string()),
                "code" => Some("code".to_string()),
                "issue" => Some("issue".to_string()),
                "milestone" => Some("milestone".to_string()),
                "pullrequest" => Some("pullRequest".to_string()),
                "review" => Some("review".to_string()),
                _ => None,
            },
        )
        .collect::<Vec<_>>();

    if menus.is_empty() {
        default_project_menu_keys()
    } else {
        menus
    }
}

fn default_project_menu_keys() -> Vec<String> {
    vec![
        "code".to_string(),
        "issue".to_string(),
        "pullRequest".to_string(),
        "review".to_string(),
        "milestone".to_string(),
        "board".to_string(),
    ]
}

fn normalize_project_default_menu_config_key(value: &str) -> String {
    value
        .chars()
        .filter(|ch| !ch.is_whitespace() && *ch != '_' && *ch != '-')
        .collect::<String>()
        .to_ascii_lowercase()
}

fn configured_supported_languages() -> Vec<String> {
    let languages: Vec<String> = std::env::var("YONA_LANGS")
        .ok()
        .unwrap_or_default()
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
        .collect();
    if languages.is_empty() {
        vec![
            "en-US".to_string(),
            "ko-KR".to_string(),
            "ja-JP".to_string(),
            "ru-RU".to_string(),
            "uz-UZ".to_string(),
        ]
    } else {
        languages
    }
}

fn gravatar_url(email_address: &str) -> String {
    let normalized = normalize_identifier(email_address);
    let mut hasher = Md5::new();
    hasher.update(normalized.as_bytes());
    format!(
        "https://www.gravatar.com/avatar/{:x}?s=256&d=identicon",
        hasher.finalize()
    )
}

fn yona_data_root() -> PathBuf {
    std::env::var("YONA_DATA")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(".yona-data"))
}

fn repository_provisioning_lock() -> &'static Mutex<()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
}

fn uploaded_files_root() -> PathBuf {
    yona_data_root().join("uploads")
}

fn uploaded_file_path(hash: &str) -> PathBuf {
    uploaded_files_root().join(hash)
}

const LEGACY_DEFAULT_MAX_FILE_SIZE: usize = 2_147_483_454;

fn max_uploaded_file_size_from_env_value(value: Option<&str>) -> usize {
    value
        .and_then(|value| value.trim().parse::<usize>().ok())
        .unwrap_or(LEGACY_DEFAULT_MAX_FILE_SIZE)
}

fn max_uploaded_file_size() -> usize {
    let env_value = std::env::var("YONA_MAX_FILE_SIZE").ok();
    max_uploaded_file_size_from_env_value(env_value.as_deref())
}

fn looks_like_utf8_text(bytes: &[u8]) -> bool {
    !bytes.is_empty()
        && std::str::from_utf8(bytes).is_ok()
        && bytes
            .iter()
            .all(|byte| matches!(*byte, b'\t' | b'\n' | b'\r' | 0x20..=0x7e | 0x80..=0xff))
}

fn upload_mime_from_magic(bytes: &[u8]) -> Option<&'static str> {
    if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        return Some("image/png");
    }
    if bytes.starts_with(b"\xff\xd8\xff") {
        return Some("image/jpeg");
    }
    if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
        return Some("image/gif");
    }
    if bytes.len() >= 12 && bytes.starts_with(b"RIFF") && &bytes[8..12] == b"WEBP" {
        return Some("image/webp");
    }
    if bytes.starts_with(b"%PDF-") {
        return Some("application/pdf");
    }
    if bytes.starts_with(b"PK\x03\x04")
        || bytes.starts_with(b"PK\x05\x06")
        || bytes.starts_with(b"PK\x07\x08")
    {
        return Some("application/zip");
    }
    None
}

fn detect_upload_mime_type(
    file_name: &str,
    declared_mime_type: Option<&str>,
    bytes: &[u8],
) -> String {
    if let Some(mime_type) = upload_mime_from_magic(bytes) {
        return mime_type.to_string();
    }

    let guessed = mime_guess::from_path(file_name).first();
    if looks_like_utf8_text(bytes) {
        if let Some(mime_type) = guessed.as_ref().map(|mime| mime.as_ref()) {
            if mime_type == "image/svg+xml" {
                return mime_type.to_string();
            }
            if mime_type.starts_with("text/") {
                return format!("{mime_type}; charset=UTF-8");
            }
        }
        return "text/plain; charset=UTF-8".to_string();
    }

    if let Some(mime_type) = guessed.as_ref().map(|mime| mime.as_ref()) {
        if mime_type != "application/octet-stream" {
            return mime_type.to_string();
        }
    }

    declared_mime_type
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("application/octet-stream")
        .to_string()
}

fn attachment_query_action(raw_query: Option<&str>) -> Option<&str> {
    raw_query
        .unwrap_or_default()
        .split('&')
        .filter_map(|pair| pair.split_once('='))
        .find_map(|(key, value)| (key == "action").then_some(value))
}

fn legacy_content_disposition_filename(file_name: &str) -> String {
    let normalized = file_name
        .chars()
        .map(|character| match character {
            ':' | '\\' | '/' | '{' | '?' => '_',
            _ => character,
        })
        .collect::<String>();
    let mut encoded = String::new();
    for byte in normalized.as_bytes() {
        match *byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'.' | b'-' | b'_' | b'*' => {
                encoded.push(char::from(*byte));
            }
            _ => encoded.push_str(&format!("%{byte:02X}")),
        }
    }
    format!("filename*=UTF-8''{encoded}")
}

fn random_storage_token() -> String {
    use base64::Engine;
    use rand::RngCore;

    let mut bytes = [0_u8; 32];
    rand::thread_rng().fill_bytes(&mut bytes);
    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(bytes)
}

fn random_site_admin_password() -> String {
    random_storage_token().chars().take(6).collect()
}

fn send_signup_verification_mail(
    to: &str,
    login_id: &str,
    verification_code: &str,
    public_origin: &str,
    base_path: &str,
) -> Result<(), ConnectError> {
    let verify_url = absolute_app_url(
        public_origin,
        base_path,
        &format!("/verify/{login_id}/{verification_code}"),
    );
    deliver(OutboundMail {
        bcc: Vec::new(),
        body: format!("User verification\n\nClick this link to verify email:\n{verify_url}\n"),
        from: default_smtp_from(),
        subject: "New Sign-up Confirm".to_string(),
        to: to.to_string(),
    })
    .map_err(internal_error)
}

fn send_password_reset_mail(
    to: &str,
    verification_code: &str,
    public_origin: &str,
    base_path: &str,
) -> Result<(), ConnectError> {
    let reset_url = absolute_app_url(
        public_origin,
        base_path,
        &format!("/resetPassword?s={verification_code}"),
    );
    deliver(OutboundMail {
        bcc: Vec::new(),
        body: format!("Copy the following URL and paste it to browser's URL bar\n\n{reset_url}"),
        from: default_smtp_from(),
        subject: format!("[{}] Password reset request", configured_site_name()),
        to: to.to_string(),
    })
    .map_err(internal_error)
}

fn send_workspace_email_validation_mail(
    to: &str,
    email_id: i64,
    token: &str,
    public_origin: &str,
    base_path: &str,
) -> Result<(), ConnectError> {
    let confirm_url = absolute_app_url(
        public_origin,
        base_path,
        &format!("/user/email/confirm/{email_id}/{token}"),
    );
    deliver(OutboundMail {
        bcc: Vec::new(),
        body: format!("Validation email\n\nConfirm this email address:\n{confirm_url}\n"),
        from: default_smtp_from(),
        subject: "Validation email".to_string(),
        to: to.to_string(),
    })
    .map_err(internal_error)
}

async fn send_project_transfer_request_mail(
    repository: &PilotRepository,
    authorization: &persistence::ProjectAuthorizationRecord,
    transfer: &persistence::ProjectTransferRecord,
    sender: &persistence::AppUserRecord,
    public_origin: &str,
    base_path: &str,
) -> Result<(), String> {
    let mut recipients = Vec::new();
    if let Some(user) = repository
        .find_user_by_login_id(&transfer.destination)
        .await
        .map_err(|error| error.to_string())?
    {
        recipients.push(user.email_address);
    } else {
        let members = repository
            .read_organization_members(&transfer.destination)
            .await
            .map_err(|error| error.to_string())?;
        recipients.extend(
            members
                .members
                .into_iter()
                .filter(|member| member.role == "org_admin")
                .map(|member| member.email_address),
        );
    }
    recipients.sort();
    recipients.dedup();

    let accept_url = absolute_app_url(
        public_origin,
        base_path,
        &format!("/project/transfer/{}/{}", transfer.id, transfer.confirm_key),
    );
    let body = format!(
        "Hello {},\n\n@{} wants to transfer the {}/{} project to {}/{}.\n{}\n\n{}\n\nIf you do not accept the transfer it will expire in a day.\n\nThanks",
        transfer.destination,
        authorization.project.owner_name,
        authorization.project.owner_name,
        authorization.project.project_name,
        transfer.destination,
        transfer.new_project_name,
        "To accept the request, visit this link:",
        accept_url,
    );
    let subject = format!(
        "[{}] @{} wants to transfer project",
        authorization.project.project_name, sender.login_id
    );
    for to in recipients.into_iter().filter(|to| !to.trim().is_empty()) {
        let _ = deliver(OutboundMail {
            bcc: Vec::new(),
            body: body.clone(),
            from: default_smtp_from(),
            subject: subject.clone(),
            to,
        });
    }
    Ok(())
}

async fn direct_request_reset_password_email(
    headers: HeaderMap,
    form: HashMap<String, String>,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
    public_origin: String,
) -> Response {
    let session = session_manager.ensure_anonymous_session(&headers);
    let redirect_path = match &backend {
        PilotBackend::Repository(repository) => {
            let login_id =
                normalize_identifier(form.get("loginId").map(String::as_str).unwrap_or_default());
            let email_address = normalize_identifier(
                form.get("emailAddress")
                    .map(String::as_str)
                    .unwrap_or_default(),
            );
            match repository
                .find_user_by_login_id(&login_id)
                .await
                .ok()
                .flatten()
            {
                Some(user) if normalize_identifier(&user.email_address) == email_address => {
                    if let Ok(code) = repository
                        .create_password_reset_verification_for_user(user.id, &user.login_id)
                        .await
                    {
                        let _ = send_password_reset_mail(
                            &user.email_address,
                            &code,
                            &public_origin,
                            &base_path,
                        );
                    }
                    "/lostPassword?requested=1"
                }
                _ => "/lostPassword?error=invalid",
            }
        }
        _ => "/lostPassword?error=unsupported",
    };

    let mut response = Redirect::to(&base_path_href(&base_path, redirect_path)).into_response();
    for cookie in session_manager.build_set_cookie_headers(&session) {
        response.headers_mut().append(
            axum::http::header::SET_COOKIE,
            cookie.parse().expect("set-cookie header"),
        );
    }
    response
}

async fn direct_reset_password(
    form: HashMap<String, String>,
    backend: PilotBackend,
    base_path: String,
) -> Response {
    let hash_string = form.get("hashString").cloned().unwrap_or_default();
    let password = form.get("password").cloned().unwrap_or_default();
    let retyped_password = form.get("retypedPassword").cloned().unwrap_or_default();

    if password.len() < 8 || password != retyped_password {
        let query = if hash_string.is_empty() {
            "/resetPassword?error=invalid".to_string()
        } else {
            format!("/resetPassword?error=invalid&s={hash_string}")
        };
        return Redirect::to(&base_path_href(&base_path, &query)).into_response();
    }

    let redirect_path = match &backend {
        PilotBackend::Repository(repository) => {
            match repository
                .find_valid_password_reset_user_id(&hash_string)
                .await
            {
                Ok(Some(user_id)) => match hash(&password, DEFAULT_COST) {
                    Ok(password_hash) => {
                        if repository
                            .update_password_hash_for_user(user_id, &password_hash)
                            .await
                            .is_ok()
                        {
                            let _ = repository
                                .delete_password_reset_verification(&hash_string)
                                .await;
                            "/users/loginform?password=reset".to_string()
                        } else {
                            format!("/resetPassword?error=invalid&s={hash_string}")
                        }
                    }
                    Err(_) => format!("/resetPassword?error=invalid&s={hash_string}"),
                },
                _ => format!("/resetPassword?error=invalid&s={hash_string}"),
            }
        }
        _ => "/resetPassword?error=unsupported".to_string(),
    };

    Redirect::to(&base_path_href(&base_path, &redirect_path)).into_response()
}

