fn redirect_to(base_path: &str, path: &str) -> Response {
    Redirect::to(&base_path_href(base_path, path)).into_response()
}

fn direct_status_from_connect_error(error: ConnectError) -> StatusCode {
    let message = error.to_string().to_ascii_lowercase();
    if message.contains("missing authenticated") {
        StatusCode::UNAUTHORIZED
    } else if message.contains("not found") {
        StatusCode::NOT_FOUND
    } else if message.contains("permission")
        || message.contains("forbidden")
        || message.contains("not allowed")
        || message.contains("invalid csrf")
    {
        StatusCode::FORBIDDEN
    } else if message.contains("invalid") || message.contains("required") {
        StatusCode::BAD_REQUEST
    } else {
        StatusCode::INTERNAL_SERVER_ERROR
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DirectCodeFileMode {
    Image,
    Open,
    Raw,
}

async fn direct_code_file(
    headers: HeaderMap,
    owner_name: String,
    project_name: String,
    revision: String,
    path: String,
    mode: DirectCodeFileMode,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
) -> Response {
    let actor_id = session_manager
        .read_session_from_headers(&headers)
        .and_then(|session| session.user_id);
    let PilotBackend::Repository(repository) = &backend else {
        return StatusCode::NOT_IMPLEMENTED.into_response();
    };
    let authorization = match repository
        .read_project_authorization(&owner_name, &project_name, actor_id)
        .await
    {
        Ok(Some(authorization)) => authorization,
        Ok(None) => return StatusCode::NOT_FOUND.into_response(),
        Err(_) => return StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    };
    let read_allowed = match project_read_allowed(&authorization, actor_id.is_none()) {
        Ok(allowed) => allowed,
        Err(_) => return StatusCode::BAD_REQUEST.into_response(),
    };
    if !read_allowed || !project_code_menu_visible(&authorization, true) {
        return if actor_id.is_none() {
            StatusCode::UNAUTHORIZED.into_response()
        } else {
            StatusCode::FORBIDDEN.into_response()
        };
    }

    let repo_path = yona_rust_vcs::repository_path(&yona_data_root(), authorization.project.id);
    match yona_rust_vcs::read_file_bytes(&repo_path, &revision, &path) {
        Ok(file) => direct_code_file_response(file, mode),
        Err(VcsError::NotFound) if mode == DirectCodeFileMode::Raw => {
            direct_code_raw_missing_redirect(
                &base_path,
                &owner_name,
                &project_name,
                &revision,
                &path,
            )
        }
        Err(error) => direct_code_file_error(error),
    }
}

async fn direct_code_archive(
    headers: HeaderMap,
    owner_name: String,
    project_name: String,
    revision: String,
    session_manager: SessionManager,
    backend: PilotBackend,
) -> Response {
    let actor_id = session_manager
        .read_session_from_headers(&headers)
        .and_then(|session| session.user_id);
    let PilotBackend::Repository(repository) = &backend else {
        return StatusCode::NOT_IMPLEMENTED.into_response();
    };
    let authorization = match repository
        .read_project_authorization(&owner_name, &project_name, actor_id)
        .await
    {
        Ok(Some(authorization)) => authorization,
        Ok(None) => return StatusCode::NOT_FOUND.into_response(),
        Err(_) => return StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    };
    let read_allowed = match project_read_allowed(&authorization, actor_id.is_none()) {
        Ok(allowed) => allowed,
        Err(_) => return StatusCode::BAD_REQUEST.into_response(),
    };
    if !read_allowed || !project_code_menu_visible(&authorization, true) {
        return if actor_id.is_none() {
            StatusCode::UNAUTHORIZED.into_response()
        } else {
            StatusCode::FORBIDDEN.into_response()
        };
    }

    let repo_path = yona_rust_vcs::repository_path(&yona_data_root(), authorization.project.id);
    match yona_rust_vcs::read_archive_zip(&repo_path, &revision) {
        Ok(bytes) => direct_code_archive_response(bytes, &project_name, &revision),
        Err(error) => direct_code_file_error(error),
    }
}

fn direct_code_archive_response(bytes: Vec<u8>, project_name: &str, revision: &str) -> Response {
    let filename = format!(
        "{}-{}.zip",
        sanitize_download_filename(project_name),
        sanitize_download_filename(revision)
    );
    let disposition = format!("attachment; filename=\"{filename}\"");
    let mut response = bytes.into_response();
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/zip"),
    );
    if let Ok(header_value) = HeaderValue::from_str(&disposition) {
        response
            .headers_mut()
            .insert(http::header::CONTENT_DISPOSITION, header_value);
    }
    response
}

fn sanitize_download_filename(value: &str) -> String {
    value
        .chars()
        .filter(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.')
        })
        .collect::<String>()
        .trim_matches('.')
        .to_string()
}

fn direct_code_file_response(file: CodeFileBytesRecord, mode: DirectCodeFileMode) -> Response {
    let content_type = match mode {
        DirectCodeFileMode::Raw => "text/plain; charset=utf-8".to_string(),
        DirectCodeFileMode::Image | DirectCodeFileMode::Open => file.mime_type,
    };
    let disposition = match mode {
        DirectCodeFileMode::Open => format!("inline; filename=\"{}\"", file.name.replace('"', "")),
        DirectCodeFileMode::Image | DirectCodeFileMode::Raw => String::new(),
    };
    let mut response = file.bytes.into_response();
    if let Ok(header_value) = HeaderValue::from_str(&content_type) {
        response
            .headers_mut()
            .insert(http::header::CONTENT_TYPE, header_value);
    }
    if !disposition.is_empty() {
        if let Ok(header_value) = HeaderValue::from_str(&disposition) {
            response
                .headers_mut()
                .insert(http::header::CONTENT_DISPOSITION, header_value);
        }
    }
    response
}

fn direct_code_file_error(error: VcsError) -> Response {
    let error = code_browser_error(error);
    error.code.http_status().into_response()
}

fn direct_code_raw_missing_redirect(
    base_path: &str,
    owner_name: &str,
    project_name: &str,
    revision: &str,
    path: &str,
) -> Response {
    let redirect_path = format!(
        "/{owner_name}/{project_name}/code/{revision}/{}",
        path.trim_start_matches('/')
    );
    Redirect::to(&base_path_href(base_path, &redirect_path)).into_response()
}

async fn direct_render_markdown(
    headers: HeaderMap,
    owner_name: String,
    project_name: String,
    body: DirectMarkdownRenderBody,
    session_manager: SessionManager,
    backend: PilotBackend,
    _base_path: String,
) -> Response {
    let markdown = body.body.as_deref().unwrap_or_default();
    if let PilotBackend::Repository(repository) = &backend {
        let actor_id = session_manager
            .read_session_from_headers(&headers)
            .and_then(|session| session.user_id);
        if let Err(error) =
            require_project_read(repository, &owner_name, &project_name, actor_id).await
        {
            return direct_status_from_connect_error(error).into_response();
        }
    }

    Json(DirectMarkdownRenderResponse {
        body_markdown: markdown.to_string(),
        breaks: body.breaks.unwrap_or(true),
    })
    .into_response()
}

#[derive(Serialize)]
struct RestErrorEnvelope {
    error: RestErrorPayload,
}

#[derive(Serialize)]
struct RestErrorPayload {
    code: &'static str,
    message: String,
    status: u16,
}

struct RestRouteError {
    code: Option<&'static str>,
    message: String,
    status: StatusCode,
}

impl RestRouteError {
    fn from_connect_error(error: ConnectError) -> Self {
        let status = error.code.http_status();
        let message = error.message.clone().unwrap_or_else(|| error.to_string());
        Self {
            code: None,
            message,
            status,
        }
    }

    fn bad_request(message: impl Into<String>) -> Self {
        Self {
            code: None,
            message: message.into(),
            status: StatusCode::BAD_REQUEST,
        }
    }

    fn not_found(message: impl Into<String>) -> Self {
        Self {
            code: None,
            message: message.into(),
            status: StatusCode::NOT_FOUND,
        }
    }

    fn not_implemented(message: impl Into<String>) -> Self {
        Self {
            code: None,
            message: message.into(),
            status: StatusCode::NOT_IMPLEMENTED,
        }
    }
}

impl IntoResponse for RestRouteError {
    fn into_response(self) -> Response {
        let code = self.code.unwrap_or(match self.status {
            StatusCode::BAD_REQUEST => "bad_request",
            StatusCode::UNAUTHORIZED => "unauthorized",
            StatusCode::FORBIDDEN => "forbidden",
            StatusCode::NOT_FOUND => "not_found",
            StatusCode::CONFLICT => "already_exists",
            StatusCode::NOT_IMPLEMENTED => "not_implemented",
            _ => "internal_error",
        });
        (
            self.status,
            Json(RestErrorEnvelope {
                error: RestErrorPayload {
                    code,
                    message: self.message,
                    status: self.status.as_u16(),
                },
            }),
        )
            .into_response()
    }
}

